import numpy as np
@njit
def count_primes_numpy_jit(n):
    assert n > 1
    isPrime = np.ones(n, dtype=np.bool_)
    isPrime[0] = isPrime[1] = 0
    for i in np.arange(2, int(n ** 0.5) + 1):
        if isPrime[i]:
            isPrime[i * i:n:i] = 0
    return int(np.sum(isPrime))

